INSERT INTO knowledge_base (content, source, source_type, metadata, embedding) VALUES
(
    'Built a 5-stage GPU approximate-nearest-neighbor (ANN) search pipeline in CUDA and OpenMP implementing FAISS-style IVF-PQ (Inverted File Index with Product Quantization) — the same core algorithm behind FAISS, Milvus, and Pinecone for large-scale vector similarity search (GPU-Accelerated Vector Search Engine, ME/CS/ECE 759 High Performance Computing graduate project at UW-Madison). Achieved a 127.8x speedup over the CPU baseline. ANN search is the backbone of RAG pipelines, recommendation systems, and image retrieval.',
    'hpc_project',
    'project',
    '{"project": "GPU-Accelerated Vector Search Engine", "category": "coursework"}'::jsonb,
