INSERT INTO knowledge_base (content, source, source_type, metadata, embedding) VALUES
(
    'Designed a shared-memory-tiled CUDA kernel for the GPU-Accelerated Vector Search Engine that cut global-memory traffic 32x and raised query throughput 6x on 1 million vectors. Further cut query latency 1.47x and index build time 2.38x via shared-memory lookup-table caching, an OpenMP-parallel k-means for codebook training, and CUDA streams for CPU-GPU pipeline overlap (CS 759 HPC graduate project).',
    'hpc_project',
    'project',
    '{"project": "GPU-Accelerated Vector Search Engine", "category": "coursework"}'::jsonb,
