INSERT INTO knowledge_base (content, source, source_type, metadata, embedding) VALUES
(
    'The RAG-Powered Portfolio Chatbot uses Google Gemini gemini-embedding-001 (768-dim) for query embeddings and a pluggable LLM layer (Groq openai/gpt-oss-120b by default, Gemini as fallback) with zero-code provider switching. It adds prompt-injection guardrails, query contextualization for pronoun resolution, and a topic filter that redirects off-topic questions using the minimum vector distance across retrieved chunks — no LLM call needed. Written by Avyakt as a portfolio project demonstrating full-stack AI infrastructure.',
    'portfolio_rag_project',
    'project',
    '{"project": "RAG-Powered Portfolio Chatbot", "category": "personal"}'::jsonb,
