INSERT INTO knowledge_base (content, source, source_type, metadata, embedding) VALUES
(
    'Built a DFA-based maximal munch lexer (lexical analyzer) with twin buffer input handling and a keyword lookup table for a custom programming language grammar (CS F363 Compiler Construction, BITS Pilani, group project 2024). A lexer tokenizes raw source code into a stream of typed tokens — the first phase of compilation. DFA maximal munch selects the longest possible valid token at each step.',
    'compiler_project',
    'project',
    '{"project": "Compiler Frontend \u2014 Lexer and Parser", "category": "coursework"}'::jsonb,
