INSERT INTO knowledge_base (content, source, source_type, metadata, embedding) VALUES
(
    'Applied the Factory design pattern via a CardGenerator class to decouple card creation logic from card type details; structured the data model around User, Deck, and Card objects with a Category classification layer. Included a comprehensive ExceptionHandling package and JavaFX GUI controllers for interactive study session management (FlashCard Application, OOP coursework at BITS Pilani).',
    'flashcard_project',
    'project',
