INSERT INTO knowledge_base (content, source, source_type, metadata, embedding) VALUES
(
    'Implemented a Mound data structure in C — an array-based probabilistic concurrent priority queue that maintains a loose heap property, enabling lock-free concurrent insert and extractMin operations without traditional mutex locking (MoundDSA, DSA coursework at BITS Pilani). A Mound is a research-grade concurrent data structure used in parallel computing contexts where multiple threads need priority-based task scheduling without contention bottlenecks.',
    'mounddsa_project',
    'project',
