INSERT INTO knowledge_base (content, source, source_type, metadata, embedding) VALUES
(
    'Avyakt Garg — MS CS student at University of Wisconsin-Madison (GPA 4.0), two-time Uber software engineering intern (AI Solutions in 2024-25, Customer Obsession in Summer 2026), and currently a UW-Madison teaching assistant for Data Management for Data Science. Background spans distributed systems engineering (Go, Kafka, gRPC, SpringBoot at Uber), GPU / HPC programming (CUDA vector search), and machine learning research (graph neural networks, medical imaging, IoT), plus full-stack AI infrastructure (RAG pipelines). Originally from New Delhi, India; BITS Pilani dual-degree graduate (CS + Biological Sciences, GPA 9.01/10). MITACS Globalink Scholar. Currently in Madison, Wisconsin, open to new-grad software and ML engineering roles for 2027.',
    'personal_bio',
    'personal',
